# Initially generated by GitHub Copilot.
def explanation_for_path(path_parts):
    if not path_parts:
        return None
    feature_name, *rest = path_parts
    if feature_name == "many-flett":
        return _many_flett_explanation(rest)
    if feature_name == "many-stress-helpers":
        return _many_stress_helpers_explanation(rest)
    if feature_name == "many-vowp":
        return _many_vowp_explanation(rest)
    if feature_name == "many-lett":
        return _many_lett_explanation(rest)
    assert False, path_parts


def _many_flett_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    flett_count = _count_from_segment(path_parts[0], "flett")
    return (
        f"that the verse contains {flett_count} distinct final-form letters, "
        "i.e. all 5 Hebrew final forms"
    )


def _many_stress_helpers_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    helper_count = _count_from_segment(path_parts[0], "stress-helpers")
    return f"that the verse contains {helper_count} distinct stress-helper patterns"


def _many_vowp_explanation(path_parts):
    assert len(path_parts) >= 3, path_parts
    vowp_count = _count_from_segment(path_parts[0], "vowp")
    lett_count = _count_from_segment(path_parts[-1], "lett")
    missing_vowps = _decode_vowp_list(path_parts[1:-1])
    return (
        f"that the verse contains {vowp_count} distinct vowel points, missing only "
        f"{missing_vowps}, and that it contains {lett_count} distinct Hebrew letters"
    )


def _many_lett_explanation(path_parts):
    assert len(path_parts) >= 2, path_parts
    lett_count = _count_from_segment(path_parts[0], "lett")
    vowp_count = _count_from_segment(path_parts[1], "vowp")
    missing_vowps = _decode_vowp_list(path_parts[2:])
    if path_parts[2:]:
        return (
            f"that the verse contains {lett_count} distinct Hebrew letters, i.e. all "
            f"27 letters when final-form letters are counted separately, and that it "
            f"also contains {vowp_count} "
            f"distinct vowel points, missing only {missing_vowps}"
        )
    return (
        f"that the verse contains {lett_count} distinct Hebrew letters, i.e. all 27 "
        f"letters when final-form letters are counted separately, and that it also "
        f"contains {vowp_count} "
        "distinct vowel points"
    )


def _count_from_segment(segment, suffix):
    prefix = f"-{suffix}"
    assert segment.endswith(prefix), segment
    return int(segment[: -len(prefix)])


def _decode_vowp_list(codes):
    decoded = tuple(_VOWP_NAMES[code] for code in codes)
    return _join_with_and(decoded)


def _join_with_and(items):
    items = tuple(items)
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"


_VOWP_NAMES = {
    ":": "sheva",
    ":∵": "ḥataf segol",
    ":_": "ḥataf pataḥ",
    ":a": "ḥataf qamats",
    "i": "ḥiriq",
    "‥": "tsere",
    "∵": "segol",
    "_": "pataḥ",
    "a": "qamats",
    "oa": "qamats qatan",
    "o": "ḥolam",
    "xxfv": "ḥolam ḥaser for vav",
    "u": "qubuts",
}


